reproduction_scripts.inplace_history_probe.py:
exec(open('build/nm-pal-next1012/history_probe.py').read().split("probe('baseline',base)")[0])
for hist,idx,pragma in itertools.product(['none','b','a','dim','slot'],['i','unused','m'],['life','cse','default']):
 s=base.replace('#pragma opt_lifetimes off',{'life':'#pragma opt_lifetimes off','cse':'#pragma opt_common_subs off','default':''}[pragma])
 # Separate original angle receiver from the final palette, preserve in-place shift.
 start=s.index('    angle = (unsigned short)');end=s.index('    p[0x20]')
 s=s[:start]+'''    angle = (unsigned short)(a + 0xa);
    w = angle;
    if (dim != 0) w = (unsigned short)(w - 4);
    p = bg + m;
    w <<= 0x1c;
    hi = w >> 16;
'''+s[end:]
 if hist in ['b','a']:
  s=s.replace('    int '+hist+';','')
  # Rename earlier scalar into hi; hi's palette assignment comes after its final prior use.
  s=re.sub(r'\b'+hist+r'\b','hi',s)
 elif hist in ['dim','slot']:
  # Copy actual parameter at entry and consume same value, no signature changes.
  marker='    b = data_0209fc50;';s=s.replace(marker,'    hi = (unsigned int)'+hist+';\n'+marker)
  if hist=='dim':s=s.replace('if (dim != 0)','if (hi != 0)')
  else:s=s.replace('func_02030958(slot)','func_02030958((int)hi)').replace('m = slot *','m = (int)hi *')
 if idx!='i':s=s.replace('    int i;','');s=re.sub(r'\bi\b',idx,s)
 probe('inplace-history-'+hist+'-idx-'+idx+'-'+pragma,s)
(out/'inplace-history-ledger.json').write_text(json.dumps(rows,indent=2))
print('count',len(rows),'best',min((r['diff'] for r in rows if r['size']==244),default=None),'roles',sorted(set(tuple(r['shift28']) for r in rows)))
print(json.dumps(sorted(rows,key=lambda r:(r['size']!=244,r['diff'] if r['diff'] is not None else 999))[:3],indent=2))

reproduction_scripts.lastuse_probe.py:
exec(open('build/nm-pal-next1012/history_probe.py').read().split("probe('baseline',base)")[0])
for chain,overwrite,loop,pragma in itertools.product(['two','inplace'],[False,True],['implicit','w','angle'],['life','cse','default']):
 s=base.replace('#pragma opt_lifetimes off',{'life':'#pragma opt_lifetimes off','cse':'#pragma opt_common_subs off','default':''}[pragma])
 if chain=='inplace':
  start=s.index('    angle = (unsigned short)');end=s.index('    p[0x20]')
  s=s[:start]+'''    angle = (unsigned short)(a + 0xa);
    w = angle;
    if (dim != 0) w = (unsigned short)(w - 4);
    p = bg + m;
    w <<= 0x1c;
    hi = w >> 16;
'''+s[end:]
 for off in ['0x20','0x40','0x37','0x57']:
  s=s.replace('(p['+off+'] & 0xfff) | hi','(p['+off+'] & 0xfff) | (w >> 16)')
 if overwrite:s=s.replace('p[0x57] = (unsigned short)((p[0x57] & 0xfff) | (w >> 16));','w = (p[0x57] & 0xfff) | (w >> 16);\n    p[0x57] = (unsigned short)w;')
 if loop!='implicit':
  for off in ['0','0x60']:
   s=s.replace('p['+off+'] = (unsigned short)((p['+off+'] & 0xfff) | hi);',loop+' = (p['+off+'] & 0xfff) | hi;\n        p['+off+'] = (unsigned short)'+loop+';')
 probe('lastuse-'+chain+'-'+str(overwrite)+'-'+loop+'-'+pragma,s)
(out/'lastuse-ledger.json').write_text(json.dumps(rows,indent=2));print('count',len(rows),'best',min((r['diff'] for r in rows if r['size']==244),default=None),'roles',sorted(set(tuple(r['shift28']) for r in rows)))
